  SPELLSTRIKE_MOD: 0.8,
  DEFAULT_CRIT_MULT: 1.5,
  IN_COMBAT_REGEN_PENALTY: 0.5,
  REGEN_BASE: 5,
  REGEN_PER_LEVEL: 1.5,
  CLASSVALUE_BASE: 13,
  CLASSVALUE_GROWTH: 1.22,
  INITIAL_AP: 40,
